import{_ as t,o as a,c as e,a5 as l}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"生活进阶工作表","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/life-practice-toolkit.zh.md","filePath":"public/downloads/worksheets/life-practice-toolkit.zh.md","lastUpdated":1795488252000}'),i={name:"public/downloads/worksheets/life-practice-toolkit.zh.md"};function d(o,r,b,h,p,n){return a(),e("div",null,[...r[0]||(r[0]=[l('<h1 id="生活进阶工作表" tabindex="-1">生活进阶工作表 <a class="header-anchor" href="#生活进阶工作表" aria-label="Permalink to &quot;生活进阶工作表&quot;">​</a></h1><p>这不是一张要求你每天满分的打卡表，而是一份帮助你重新看见现实的私有记录。遇到重要选择、注意力失控、关系冲突、长期疲惫或需要分担的照料事务时，复制对应部分，写下事实和下一步。</p><p>请把文件放在自己的私有笔记或项目目录里。不要写入密码、证件号码、精确住址、医疗隐私、客户资料或未获授权的第三方信息。涉及紧迫危险、持续失眠、严重低落、暴力、债务或法律责任时，优先联系合格的专业支持。</p><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ol><li>先写日期和当前问题，不急着解释自己；</li><li>只填写与当前问题相关的一张表；</li><li>每次留下一个可执行动作和一个证据位置；</li><li>在约定日期回来复查，不用结果倒推当时的人格；</li><li>每周删除已经无用的记录，保留能帮助下一次判断的事实。</li></ol><h2 id="一、选择简报" tabindex="-1">一、选择简报 <a class="header-anchor" href="#一、选择简报" aria-label="Permalink to &quot;一、选择简报&quot;">​</a></h2><h3 id="选择简报-—-yyyy-mm-dd" tabindex="-1">选择简报 — YYYY-MM-DD <a class="header-anchor" href="#选择简报-—-yyyy-mm-dd" aria-label="Permalink to &quot;选择简报 — YYYY-MM-DD&quot;">​</a></h3><p>要解决的问题：<br> 必须在什么时候决定：</p><p>已知事实与来源：<br> 我的解释：<br> 仍然未知：<br> 问题类型：信息不足 / 结果不确定 / 价值冲突 / 身份防卫<br> 不可谈判的价值与底线：</p><p>选项 A：<br> 选项 B：<br> 暂不行动：</p><p>每个选项的收益：<br> 每个选项的金钱成本：<br> 每个选项的健康成本：<br> 每个选项对关系和责任的影响：<br> 哪些部分可逆：</p><p>最小实验：<br> 证据门槛及复查日期：<br> 成本门槛：<br> 安全门槛：<br> 责任门槛：<br> 触发后采取：暂停 / 停止 / 回滚 / 升级求助<br> 什么证据会推翻当前选择：</p><p>提议者：<br> 最终决定者及其权限依据：<br> 受影响的人及其实际承担：<br> 需要明确同意的事项：<br> 执行者及所需资源：<br> 复查者及暂停权限：<br> 需要征求谁的意见：<br> 当前决定：<br> 复查日期：<br> 决定之后留下的证据：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-2/decision" target="_blank" rel="noreferrer">选择篇：在不确定中做决定</a>；决定涉及共同生活、隐私或不对等权力时，同时使用<a href="https://byoungd.github.io/up/threads/part-2/relationships" target="_blank" rel="noreferrer">关系篇</a>检查同意与退出通道。</p><h2 id="二、注意力审计" tabindex="-1">二、注意力审计 <a class="header-anchor" href="#二、注意力审计" aria-label="Permalink to &quot;二、注意力审计&quot;">​</a></h2><h3 id="注意力审计-—-yyyy-mm-dd-至-yyyy-mm-dd" tabindex="-1">注意力审计 — YYYY-MM-DD 至 YYYY-MM-DD <a class="header-anchor" href="#注意力审计-—-yyyy-mm-dd-至-yyyy-mm-dd" aria-label="Permalink to &quot;注意力审计 — YYYY-MM-DD 至 YYYY-MM-DD&quot;">​</a></h3><p>本周最重要的问题：</p><table tabindex="0"><thead><tr><th>区域</th><th>本周事实</th><th>带来的结果</th><th>下周调整</th></tr></thead><tbody><tr><td>输入：阅读、视频、会议、聊天</td><td></td><td></td><td></td></tr><tr><td>切换：通知、临时任务、无意识浏览</td><td></td><td></td><td></td></tr><tr><td>输出：作品、决定、复述、交付</td><td></td><td></td><td></td></tr><tr><td>关系：真正投入在场的谈话</td><td></td><td></td><td></td></tr><tr><td>身体：睡眠、活动、精力</td><td></td><td></td><td></td></tr></tbody></table><p>本周要关闭的一个入口：<br> 本周要保护的一个 25–45 分钟时间盒：<br> 使用 AI 前我已经知道：<br> 关闭 AI 后我还能独立完成：<br> 下一周只做的一个实验：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-3/3-attention-and-judgment" target="_blank" rel="noreferrer">注意力篇：把注意力还给自己</a></p><h2 id="三、关系沟通卡" tabindex="-1">三、关系沟通卡 <a class="header-anchor" href="#三、关系沟通卡" aria-label="Permalink to &quot;三、关系沟通卡&quot;">​</a></h2><h3 id="关系沟通卡-—-yyyy-mm-dd" tabindex="-1">关系沟通卡 — YYYY-MM-DD <a class="header-anchor" href="#关系沟通卡-—-yyyy-mm-dd" aria-label="Permalink to &quot;关系沟通卡 — YYYY-MM-DD&quot;">​</a></h3><p>关系与场景：<br> 谁掌握更多资源、评价权、账号、信息或退出成本：<br> 我希望这次谈话完成什么：<br> 对方是否可以安全地拒绝、暂停或退出这次谈话：<br> 是否获得记录、上传、转发或公开材料的明确同意：</p><p>我观察到的具体事实：<br> 我受到的影响和感受：<br> 我真正需要的是什么：<br> 我希望对方考虑的一个具体请求：<br> 我能执行的边界：<br> 哪些责任属于我，哪些不属于我：<br> 如果谈话变得不安全，我会联系：</p><p>谈话后记录：</p><ul><li>对方实际说了什么：</li><li>我是否真正听完：</li><li>我们明确同意了什么，没有同意什么：</li><li>谁负责哪个动作，何时完成：</li><li>哪个修复可以被观察，而不以原谅或和好为条件：</li><li>哪个问题仍未解决：</li><li>下一次何时复查：</li></ul><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-2/relationships" target="_blank" rel="noreferrer">关系篇：在关系中成为成年人</a></p><h2 id="四、恢复重置表" tabindex="-1">四、恢复重置表 <a class="header-anchor" href="#四、恢复重置表" aria-label="Permalink to &quot;四、恢复重置表&quot;">​</a></h2><h3 id="恢复重置-—-yyyy-mm-dd" tabindex="-1">恢复重置 — YYYY-MM-DD <a class="header-anchor" href="#恢复重置-—-yyyy-mm-dd" aria-label="Permalink to &quot;恢复重置 — YYYY-MM-DD&quot;">​</a></h3><p>今天最需要保护的安全事项：<br> 可以联系的人：<br> 需要暂停的高风险决定：<br> 今天的模式：安全 / 降档 / 重建<br> 如果安全恶化，我会停止什么、联系谁、去哪里：</p><p>身体：</p><ul><li>睡眠情况：</li><li>吃过什么：</li><li>可以完成的轻量活动：</li><li>需要咨询的专业支持：</li></ul><p>基本生活底线：饮食 / 睡眠准备 / 必要照护 / 关键账单与沟通<br> 今天的一个最小任务：<br> 任务完成证据：<br> 任务上限和结束时间：<br> 第二天需要检查的代价：<br> 今天允许自己不做的事：<br> 明天打开文件后要做的第一步：</p><p>支持协议：</p><ul><li>支持者可以做：</li><li>支持者不能替我做：</li><li>需要升级求助的信号：</li><li>风险降低后如何归还账号、文件和决定权：</li><li>只分享完成安全任务所需的最少信息：</li></ul><p>复工门槛：</p><ul><li>安全门槛：</li><li>基本生活门槛：</li><li>限时任务门槛：</li><li>边界沟通门槛：</li><li>复查日期与有权暂停的人：<br> 下一次只增加的一个变量：</li></ul><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-2/recovery" target="_blank" rel="noreferrer">恢复篇：先把自己接住</a></p><h2 id="五、关心与分担卡" tabindex="-1">五、关心与分担卡 <a class="header-anchor" href="#五、关心与分担卡" aria-label="Permalink to &quot;五、关心与分担卡&quot;">​</a></h2><p>选一件可以讨论的具体事务，例如接送、买菜、陪伴、安排休息或处理账单。先询问需要，再确认双方愿意承担什么。这张卡不用于给爱打分、监控行踪或要求对方汇报；只保留双方同意记录的最少信息。家人或伴侣不是必需的支持者，可以寻找朋友、社区或专业支持。孩子可以参与符合年龄、能够拒绝的小事，但不能承担成人的情绪安抚、冲突调解或拯救责任。</p><h3 id="关心与分担卡-—-yyyy-mm-dd" tabindex="-1">关心与分担卡 — YYYY-MM-DD <a class="header-anchor" href="#关心与分担卡-—-yyyy-mm-dd" aria-label="Permalink to &quot;关心与分担卡 — YYYY-MM-DD&quot;">​</a></h3><p>当前需要关心的人或需要分担的具体事务：<br> 对方表达的需要（尚未询问时写“未知”）：<br> 我希望表达的一句关心或感谢：</p><p>我可以自行承担的具体任务：<br> 我需要支持的具体任务：<br> 哪些任务可以减少、推迟或停止：<br> 我目前愿意提供的时间、精力或资源上限：<br> 对方目前愿意提供的时间、精力或资源上限（未确认时写“未知”）：<br> 对方是否愿意参与这次讨论和记录：<br> 双方怎样拒绝、暂停或调整，而不被指责、报复或要求证明爱：<br> 如果对方无法支持，我可以联系的其他人或服务：<br> 哪些成人责任必须留在成人和适当支持者手中：</p><p>共同决定的下一步（没有共同决定时不替对方填写）：</p><ul><li>我愿意负责的动作及完成时间：</li><li>对方明确同意负责的动作及完成时间：</li><li>暂不承担或需要外部支持的部分：</li><li>我们同意保留哪些信息、保存在哪里、何时删除：</li></ul><p>下一次复查日期：<br> 需要提前减轻负荷或求助的信号：<br> 复查时：这项安排是否仍然自愿、是否太重、需要怎样调整：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-2/care-and-carry-on" target="_blank" rel="noreferrer">珍惜篇：从爱与牵挂中获得力量</a>；涉及边界、拒绝或修复时，同时阅读<a href="https://byoungd.github.io/up/threads/part-2/relationships" target="_blank" rel="noreferrer">关系篇</a>。</p><h2 id="六、每周复盘" tabindex="-1">六、每周复盘 <a class="header-anchor" href="#六、每周复盘" aria-label="Permalink to &quot;六、每周复盘&quot;">​</a></h2><p>每周只回答五个问题：</p><ol><li>哪个事实改变了我的判断？</li><li>哪个动作留下了可以检查的结果？</li><li>哪个错误在重复，它的可能原因是什么？</li><li>哪个边界需要说得更清楚或执行得更坚定？</li><li>下周只保留哪一个最小实验？</li></ol><p>把这份工作表和<a href="https://byoungd.github.io/up/templates/weekly-review" target="_blank" rel="noreferrer">每周复盘模板</a>放在同一个私有目录里。记录不是为了把生活变成表格，而是为了在情绪最响亮的时候，仍然有一小块事实可以站立。</p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/life-practice-toolkit" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-10-04。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',53)])])}const y=t(i,[["render",d]]);export{u as __pageData,y as default};
